insert into `slides` values ('2','轮播图2','内容2','/article/details?article=2','/api/upload/1597081608173649920.jpg','860','2023-05-07 14:10:42.0','2023-05-07 14:10:42.0');
insert into `slides` values ('3','轮播图3','内容3','/article/details?article=3','/api/upload/1597081675882299392.jpg','27','2023-05-07 14:10:42.0','2023-05-07 14:10:42.0');
insert into `article` values ('1','2022国漫崛起？是否能创造国创动漫新纪元？','动漫','647','0','2023-05-07 14:10:43.0','2023-05-07 14:10:43.0',null,null,null,'<p><br></p><p>“近几年，国漫也涌现了许许多多优秀的作品，被人称颂，口碑爆表，说国漫终于要崛起。”</p><p><br></p><p>当然，国漫的崛起必须借助优质作品，才能创造国创动漫新纪元。</p><p><br></p><p>相较于美漫、港漫、日漫的成熟体系，固有风格，国漫要想崛起？可能需要漫长的时间。</p><p><br></p><p>我们应该把握核心：我们的特色是什么？中国风。中国风的精髓是什么？</p><p><img src="data:image/jpeg;base64,"></p><p><br></p><p>在我看来，中国风便是古风，便是那水墨晕染的江南，那烟雨朦胧的过去。</p><p>月色被打捞起，晕开了结局。为何方文山的词可以如此美艳惊人？</p><p>思绪成墨，为君写浓淡。为何淡淡几字，感触深远。</p><p>虽然中国风的受众面可能比较小，但国之精华，何以摒弃？</p><p>相信很多人都曾看过动漫短片《相思》，那部曾一度刷爆朋友圈的口碑神作。故事以王维的《相思》为背景，讲述了嘉定名士王初桐和发小六娘青梅竹马、红豆定情却无缘厮守的爱情故事。</p><p><br></p><p><br></p><p><br></p><p>可能感触颇深的，是小秀才和六娘的爱情，但那缓缓展开的烟雨画面，却是一下子深入了我心，不可自拔。</p><p>或许小时候，大家都接触过水墨画，寥寥几笔，水牛、鱼虾便能跃然纸上，这才是国之精华。</p><p>我相信优质作品一定会助力国漫崛起，创造国创动漫新纪元。</p>','/api/upload/1589891617093844993.jpg',null);
insert into `article` values ('2','第十三届动漫博览会已定档！！11月相约东莞厚街！','动漫','366','0','2023-05-07 14:10:43.0','2023-05-07 14:10:43.0',null,null,null,'<p>第十三届中国国际影视动漫版权保护和贸易博览会（以下简称“第十三届动漫博览会”）拟于2022年11月17日至20日（周四至周日）在东莞市厚街镇广东现代国际展览中心3号馆举办。</p><p><br></p><p><br></p><p><br></p><p>届时，格林童话、银魂、芝麻街、绿巨人、街头霸王、宝可梦、樱桃小丸子、仙境传说、甜品怪兽、太空飞鼠、我的英雄学院、奇奇和努娜、超级飞侠、小凉帽、敦煌IP、仙剑奇侠传、唐宫夜宴、星际熊、少年歌行、我是不白吃、非人哉、吾皇猫、加菲猫、派灵灵、汪柴主、中国奇谭等国内外知名IP都将参展参会。</p><p><br></p><p><br></p><p><br></p><p>第十三届动漫博览会由国家广播电视总局、广东省人民政府主办，由东莞市人民政府、广东省广播电视局、广东省文化和旅游厅、广东省版权局和广东广播电视台承办。</p><p><br></p><p><br></p><p><br></p><p>中国国际影视动漫版权保护和贸易博览会</p><p><br></p><p><br></p><p><br></p><p>中国动漫博览会充分发挥粤港澳大湾区区位优势</p><p><br></p><p>以培育优质影视动漫品牌为核心</p><p><br></p><p>以促进版权保护和贸易为特色</p><p><br></p><p>致力于打造中国影视动漫优质内容孵化器</p><p><br></p><p>产业发展助推器和品牌出海牵引器</p><p><br></p><p>培育最具特色的影视动漫IP高端交易平台</p><p><br></p><p>助推我国影视动漫产业高质量发展</p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p>展会信息</p><p><br></p><p>展会秉持“守正创新、开放合作、展产结合、展城共融”的办展理念，突出展示影视动漫全产业链条，打造粤港澳大湾区影视动漫产业对接示范平台。</p><p><br></p><p><br></p><p><br></p><p>规划展览总面积约20800平方米，计划共设置国际标准展位1600+，将汇聚1500+国内外知名影视动漫以及潮流潮玩IP。</p><p><br></p><p><br></p><p><br></p><p><br></p><p>展会将开展专业展览、专业论坛、产业对接、原创培育、潮流文化、版权保护等线上与线下结合、虚拟与现实融合、国际与国内互通的配套产业活动，打造“4+365”永不落幕的国际化影视动漫盛会。</p><p><br></p><p><br></p><p><br></p><p><br></p><p>汇集国内外知名影视动漫企业参展</p><p><br></p><p>第十三届动漫博览会以更多元、更丰富、更有趣的方式全方位展现影视动漫产业生态。</p><p><br></p><p><br></p><p><br></p><p><br></p><p>往届动漫博览会▲</p><p><br></p><p><br></p><p><br></p><p>截至目前，包括央视动漫、上美影、奥飞娱乐、华侨城、中国动漫集团、中影年年、中手游、重力聿画、一间宇宙、玩拓、雷曦文化、分子互动、广东嘉佳少儿频道、天闻角川、唐宫夜宴、顺林模型、亚马逊、摩动核、星际熊、幸会潮玩、超次元等在内的200+企业将亮相本届展会。</p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p>提供专业化展览展示空间</p><p><br></p><p>为更好地方便参展企业和采购商双方以及观众的供需明确、便利，提供专业化展览展示空间，第十三届动漫博览会场地面积超2万平方米。</p><p><br></p><p><br></p><p>图片</p><p><br></p><p>展期主会场设动漫产业链全景展</p><p><br></p><p><br></p><p>动漫原创内容展▲</p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p>动漫供应链与平台生态展▲</p><p><br></p><p><br></p><p><br></p><p><br></p><p>动漫商贸渠道展▲</p><p><br></p><p><br></p><p><br></p><p><br></p><p>专业活动</p><p><br></p><p><br></p><p><br></p><p>“动感金羊”优秀作品扶持计划项目▲</p><p><br></p><p><br></p><p><br></p><p>动感金羊扶持计划是中国国际影视动漫版权保护和贸易博览会的重要配套活动，自2015年以来，项目共收到14207件作品，获扶持作品300件，为我国动漫产业发展搭建了交流平台，对完善我国影视动漫产业链条，推动动漫产业高质量发展起到了不可忽视的作用。</p><p><br></p><p><br></p><p><br></p><p><br></p><p>展会设三场主题论坛</p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p>中国动画产业大会▲</p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p>“Z世代”潮流文化产业论坛▲</p><p><br></p><p><br></p><p><br></p><p><img src="data:image/png;base64,"></p><p><br></p><p>电视动画高质量发展座谈会▲</p><p><br></p><p><br></p><p><br></p><p>产业对接会 精准邀约专业观众10000+</p><p><br></p><p><br></p><p>本届动漫博览会将举办超过20场丰富多样的产业对接会，包括“IP+食品”“IP+品牌”“IP+渠道”“IP+玩具”“IP+文具”等活动，并邀请品牌商发布需求、进行优秀动漫人才推荐、开展招商发布会等专场活动。聚焦产业热点，发掘行业趋势，推动跨界合作，促进动漫产业高质量发展。</p><p><br></p><p><br></p><p><br></p><p><br></p><p>展前及展期配套公众活动丰富</p><p><br></p><p>为进一步彰显东莞城市魅力，培育潮流文化消费环境，丰富大众文化生活。本届动漫博览会将策划潮玩精品文化专项活动，打造东莞潮流嘉年华活动，营造潮流之都文化氛围。</p><p><br></p><p><br></p><p><br></p><p>展前通过探店、探厂、探校园活动营造潮流文化氛围，展期举办系列展演活动，汇聚潮流企业、潮流品牌、潮流玩具、潮玩社团等文化领域人群。</p><p><br></p><p><br></p><p>潮流文化嘉年华▲</p><p><br></p><p><br></p><p><br></p><p>潮流文化嘉年华能够促进潮流圈层的互动交流，充分展现东莞青春之城精彩活力。讲好东莞潮流故事，展现“潮流之都”风采。</p><p><br></p><p><br></p><p><br></p><p>现场将举办包括动漫潮流嘉年华国潮SHOW、电竞赛事、转笔大赛、动漫人偶巡游、COSPLAY演出、潮牌走秀及街舞表演、涂鸦表演、虚拟数字人潮牌体验秀等活动，充分展现东莞青春之城的精彩活力，做强做实东莞潮流产业品牌建设。</p><p><br></p><p><br></p><p>潮流文化嘉年华▲</p><p><br></p><p><br></p><p><br></p><p>媒体合作宣传</p><p><br></p><p><br></p><p>第十三届动漫博览会将广泛征集国内国际新闻媒体、广播电视、报刊杂志、门户网站、自媒体KOL等传统媒体与新媒体成员，为影视动漫、潮玩产业进行全媒渠道、全方位、多角度地联动报道与传播，为优秀的展商以及设计师发声，实现资源整合、价值共享。</p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p>后续将继续推送第十三届动漫博览会</p><p><br></p><p>观展登记等相关信息</p><p><br></p><p>请各位朋友粉丝保持密切关注</p><p><br></p><p>2022年11月17日-20日</p><p><br></p><p>让我们再次相约潮流之都——东莞</p><p><br></p><p>为您呈现更多精彩</p>','/api/upload/1589890130187911168.jpg','第十三届动漫博览会');
insert into `article` values ('3','你可曾发现融合在生活里的动漫世界？','动漫','516','0','2023-05-07 14:10:43.0','2023-05-07 14:10:43.0',null,null,null,'<p>在如今这个联名当道，爆款云集的球鞋热潮中，好似越来越少的单品鞋款能被众人所铭记，除了那些年代久远的复刻鞋款，那些联名加持的重磅鞋款；那些被各式标签灌注的奇特鞋款......</p><p>由此可见标签对于一款单品的附加价值举足轻重，动漫作为当代一众年轻人的回忆，其中的意义除了动漫本身带给我们的快乐外，还有那些无法磨灭的青春记忆，不知当响起某首主题曲时，你也会和大多数一样热血沸腾呢？</p><p>今天小编就为大家盘点那些与动漫联名的球鞋单品！</p><p>（以下排名不分先后顺序，欢迎大家补充）</p><p>▶ Dragon Ball</p><p><br></p><p>一部有血有肉的动漫似乎定然深得人心，龙珠系列就是如此，从最初的七龙珠到后面的龙珠Z，龙珠剧场版等等，每一部都让人回味无穷。作为是1986年连载动画《龙珠》，其中蕴含的众多元素，放到今天的设计中，也丝毫不会过时，早在18年，adidas就曾与Dragon Ball Z系列共同发布过系列联名鞋款，除了鞋款本身的各处配色细节加持外，不得不提的就是有意思的鞋盒设计，最初发布的七双球鞋的鞋盒拼凑在一起，就可呈现出包含七位角色的神龙图，此后Anta等品牌也与龙珠系列发布过联名单品。</p><p><br></p><p>▶ Gundam</p><p><br></p><p><br></p><p>Nike追溯之前Dunk的热潮，在去年发布了与Gundam的联名鞋款，模型。Gundam作为儿时“机器人”的代名词，毫无疑问拥有着超高的人气，即使你以前并没有看过高达系列，但凭借炫酷的外形，就足以让无数喜爱动漫的男生直呼过瘾，而与之相关联的鞋款，更是成为了动漫联名里的经典单品之一。而Nike此次选择的作品也是这几年口碑不错的Mobile Suit Gundam UC，其中球鞋联名的Banshee和Project Unicorn White正是其中可以开启NT-D的型号，除了整体的配色呼应外，此次的联名也加入了许多可玩性的细节进去，例如可活动的Swoosh Logo，附赠的贴纸等，魔术贴式的更换设计，可谓是趣意十足。</p><p><br></p><p>▶ Transformers</p><p><br></p><p>2007年，当源于动漫的Transformers被搬上影院的银幕之后，变形金刚系列好像成为了那些年的“国际大片”的代表，不知有多少人和小编一样的为之沸腾。Nike为此以Nike Free 7.0为原型，打造了属于Transformers系列的鞋款。</p><p><br></p><p><br></p><p><br></p><p>▶ 通灵男孩诺曼</p><p><br></p><p><br></p><p><br></p><p><br></p><p>要说起当年的天价鞋款，定然少不了Nike Air Foamposite One通灵男孩，也就是大家熟知的“通灵男孩喷”。整体鞋子的风格可谓是和该部动漫交相呼应，鞋身与通灵相呼应的绿色火焰，似乎比普通的火焰更有魅力。</p><p><br></p><p><br></p><p><br></p><p>@Giantfanjay</p><p><br></p><p><br></p><p>▶ 灌篮高手</p><p><br></p><p><br></p><p>据之前的消息看，灌篮高手的剧场版将于今年的12月3日正式播出，小编直呼：爷青回！而说到灌篮高手，其中相关配色的球鞋真是让人回忆满满，红和黑是湘北的颜色！小编今天放上来的这双是Air Jordan 6 樱木花道，这次Salm Dunk x Nike Jordan Brand以 Air Jordan 6 为范本，并将漫画中最后一战湘北与山王工高的对决画面设计在鞋盒上，重现当初樱木花道舍身救球的画面，可谓是栩栩如生。</p><p><br></p><p>▶ 哆啦A梦</p><p><br></p><p><br></p><p><br></p><p>哆啦A梦真的是小编童年的究极回忆了，当时记得有个播放软件上面每天会播放机器猫的大全集一共1000多集，可以用大满足来形容！以至于小编现在看到许多红蓝配色的单品，都有不一样的感觉...好了废话不多说，哆啦A梦联名鞋款，相信大家印象最为深刻的就是之前Nike Dunk High “Doraemon”，整体白色鞋面穿插蓝色，搭配红色的Swoosh Logo ，黄色的 NIKE SB 标签位于鞋舌，也是整双鞋的中间处位置，恰好对应哆啦 A 梦的四次元口袋。但其实早些时候就发布过一款atmos x Packer Shoes x Reebok Instapump Fury的三方联名鞋款</p><p><br></p><p><br></p><p><br></p><p>▶ 海贼王</p><p><br></p><p><br></p><p><br></p><p>你是要成为海贼王的男人吗？近期，Vans发布了海贼王系列鞋款，Sk8-Hi 印花360度包裹鞋面，高度还原了动漫岛屿的元素，Authentic的黄麻织物材质鞋面，完美演绎了传统航海风格，Old Skool的数码艺术印花，重温伟大航路冒险！</p><p><br></p><p><br></p><p>除了以上这些之外，大家最印象深刻的动漫球鞋是哪一双呢？或者说你最难以割舍的动漫是哪一部呢？欢迎大家补充私信我们~</p>','/api/upload/1589883792732979201.jpg',null);
insert into `article` values ('4','《因为不是真正的同伴》第二季制作决定，《为丑女献上花束》动画化','动漫','720','0','2023-05-07 14:10:43.0','2023-05-07 14:10:43.0',null,null,null,'<p>《想当冒险者的女儿到大都市当了等级S的冒险者》动画化</p><p>一部异世界轻改动画，讲述的是冒险者贝尔格里夫由于膝盖受了伤而回到故乡生活。某一天，意外在森林里见到一个被遗弃的小女孩，男主领养了她并取名为安洁琳。</p><p>受男主的影响，安洁琳自小就梦想着能成为冒险者，并且直至12岁这年以冒险者为目标离开了家乡。四年后，等到安洁琳成为S级冒险者，准备回家探望父亲时，却由于陆续出现的魔物挡住了路。</p><p>一边是担心女儿的男主，另一边是归乡心切的安洁琳，一场关于亲情和友情的异世界故事就此展开。</p><p>本作的风格和大多数同类作品都不一样，并非冒险向的爽文，而是走得治愈温馨的路线。实际的表现如何，一起期待吧。</p><p><img src="data:image/jpeg;base64,"></p><p><br></p><p><br></p><p>《暴食的巴萨卡》动画化</p><p>又名《狂怒的暴食 ～只有我突破了等级这概念～》。讲述的是男主角菲特有着暴食的技能，无论吃多少都会感到饿。由于对能力没任何帮助，他一直觉得这是个很鸡肋的技能。</p><p>直至有一天，男主解决了敲入城堡的盗贼后，才发现暴食技能的真正用处：能够吞噬对方的灵魂，并获取全部的力量。并且，男主第一次感受到了饱腹感。</p><p>在这之后，他选择成为武人，并逐渐崭露头角，朝着变强的道路不断前行。</p><p>该作目前只宣布了动画化的制作决定消息，动画的制作阵容以及播出时间还未公布。</p><p><br></p><p><br></p><p>《因为不是真正的伙伴而被逐出勇者队伍》第二季</p><p>一部异世界轻改动画，第一季于去年十月播出。在剧情上，讲述的是因为被认为拖了后腿，男主角被赶出了勇者队伍。在这之后，他来到一座边境小镇，并在这里开起了药草店，过上了悠哉的慢生活。</p><p>第一季动画由Wolfs Bane和Studio flad共同制作，导演为星野真。</p><p>直至完结近一年后，本作与近日宣布将会推出第二季。</p><p><br></p><p><br></p><p>《为丑女献上花束》动画化</p><p>本作是作楽 ロク创作的一部校园恋爱向漫画。女主角田端花是个外表很不起眼，身边没有任何朋友的孤独的高中生。因为怕被被人嘲笑的缘故，就连早上浇花都会早早来到教室。</p><p>某一天，就在她在教室里独自扮演着梦想中的女主角时，突然被班上的现充，也就是男主角看到。</p><p>以此为契机，两人之间的关系有了飞速发展。一场搞笑恋爱故事就此展开。</p><p><br></p><p><br></p><p><br></p><p>《网购技能开启异世界美食之旅》动画化</p><p>标题虽然很简单，但已经将全作的剧情设定交代得差不多了。作品讲述的是男主角向田刚志是个平凡的上班族，某一天意外被召唤到异世界。在这里，他被赋予的唯一技能就是“网购”——可以将现代世界超市的商品，买到异世界。</p><p>利用这项能力，男主开启了自己的异世界美食之路。并且，陆续吸引到不少同伴。</p><p><br></p><p><br></p><p>相较于毫无新意的剧情，本作的动画制作才是最让人意外的地方。制作公司为最近几年口碑直线上升的MAPPA，导演为松田清。</p><p>动画的具体开播时间为明年一月。</p>','/api/upload/1589885174592569344.jpg',null);
